    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AB = 6</span>  و  <span dir=\"ltr\" class=\"expr pt\">CD = 5</span>  و  <span dir=\"ltr\" class=\"expr pt\">AD = 4</span>  و  <span dir=\"ltr\" class=\"expr pt\">(AB) // (CD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">(EF) // (AB)</span>"},{"quoi":"القاعدة","math":"بتطبيق نظرية طالس على كلّ متوازيين، نحصل على العلاقة بين النّسب"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">(AB) // (CD)</span>  إذن  <span class=\"frac\" dir=\"ltr\"><span class=\"num\">EF</span><span class=\"den\">AB</span></span> + <span class=\"frac\" dir=\"ltr\"><span class=\"num\">EF</span><span class=\"den\">CD</span></span> <span dir=\"ltr\" class=\"expr\">= 1</span>"},{"quoi":"النتيجة","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">EF</span><span class=\"den\">AB</span></span><span dir=\"ltr\" class=\"expr\"> + </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">EF</span><span class=\"den\">CD</span></span><span dir=\"ltr\" class=\"expr\"> = 1</span>"}],
